    for (const file of [
      'extension/src/speech/stt-port.js',
      'src/speech.ts',
      'app/lib/voice.tsx',
      'packages/web/audio.mjs',
      'assistant.cjs',
      'client/jsx/mic.jsx',
    ]) expect(isSource(file), file).toBe(true);
  });

