    for (const file of [
      'extension-test/unit/speech-ports.test.js',
      'src/speech.spec.ts',
      'test/voice.js',
      '__tests__/mic.js',
      'src/__mocks__/recognition.js',
      'test/fixtures/fake-recognizer.js',
      'node_modules/some-pkg/speech.js',
      'dist/bundle.js',
      'README.md',
    ]) expect(isSource(file), file).toBe(false);
  });
